import pages as PG
from pages import *
from pages import foreword,glance,reading,story,cards,end,sources,build,covart,verse
from fx import *
PG.configure('/festivals/hanuman-jayanti/',[('','Hanumān Jayantī','The Birth of Rāma’s Messenger')],'blue','Hanumān Jayantī','Lord','Hanumān Jayantī')
PG.CFG.update(backurl='/festivals/',backname='all festivals')
PG.OUT='outd/hanuman-jayanti/'
i=0
H=lambda: hanuman()
RAMA=lambda: god('#2a5aa8')
SITA=lambda: person('#c0392b')
def gada(): return mace()
def herbhill(): return mountain('#6a8a5a',False)+''.join(f'<circle cx="{x}" cy="{y}" r="3" fill="#ffd60a" stroke="none"/>' for x,y in [(-10,-20),(6,-30),(14,-14),(-4,-8)])
def vadamala(): return '<path d="M-40 -40 q40 70 80 0" fill="none" stroke="#8a5a3a" stroke-width="2"/>'+''.join(f'<circle cx="{-40+k*10}" cy="{-40+28*__import__("math").sin(k*0.39)}" r="5" fill="#c98a3a"/>' for k in range(9))
def ring(): return '<circle r="10" fill="none" stroke="#e0a800" stroke-width="4"/><circle cy="-10" r="4" fill="#c0392b"/>'
def ocean(w=144,y=120): return river(w,y,'#5a8ab8')
COV=covart('Hanumān leaping across the sky with a mountain in one hand, the sun behind him, the sea below and a hill temple',f'<rect width="440" height="196" fill="#e3eaf3"/>'+g(360,50,1.2,sun(24))+'<path d="M0 160 q110 -10 220 0 t220 0 v36 h-440z" fill="#5a8ab8"/>'+g(220,130,1.5,H(),rot=-20)+g(290,70,.7,herbhill())+g(70,170,.9,mountain('#8a9a8a',False))+g(70,128,.5,palace()))
pp=[foreword(i,['<b>Hanumān</b> is everybody’s god: the strongest, the humblest, the most learned, the most devoted. Almost every Karnataka village has an Āñjaneya temple, often the oldest shrine in the place, at the boundary or under a great tree. His birthday is kept on different days in different regions, and in Karnataka on the bright thirteenth of Mārgaśīrṣa as the <b>Hanumad vrata</b>.','This article explains why there are several birthdays, tells his birth and childhood as Vālmīki and the Purāṇas tell them (the curse on Añjanā, the wind god, the leap at the sun), his great deeds for Rāma, gives three verses sung to him, and goes to <b>Añjanādri</b> near Hampi, where lakhs of devotees end their Hanumān-mālā vow.'],[('z','Why does Hanumān have so many birthdays?'),('b','Different regions read the old texts differently, Zappy. Hanumān doesn’t mind more parties.')]),
 glance([('Who','Hanumān, Āñjaneya, Māruti: son of Añjanā and Kesarī, and of Vāyu the wind; servant of Rāma'),('Karnataka','Hanumad vrata: Mārgaśīrṣa Śukla Trayodaśī (Nov–Dec)'),('North','Caitra Pūrṇimā (March–April)'),('Telugu states','Vaiśākha Daśamī, after a 41-day dīkṣā from Caitra Pūrṇimā'),('Tamil Nadu, Kerala','Mārgaḻi new moon with the Mūla star; Odisha: Pāṇa Saṅkrānti'),('Karnataka’s great event','Hanumān-mālā visarjane on Añjanādri, near Hampi'),('Texts','Vālmīki Rāmāyaṇa (Kiṣkindhā 66, Sundara Kāṇḍa); Brahmāṇḍa and other Purāṇas; Tulasīdās’s Cālīsā')],svg(560,140,'Hanumān with his mace and a hill shrine',f'<rect width="560" height="140" fill="#e3eaf3"/>'+g(200,130,1.2,H())+g(260,110,1,gada())+g(420,130,.8,mountain('#8a9a8a',False))+g(420,95,.4,palace()))),
 reading('dates','SEVERAL BIRTHDAYS','Why the date differs',svg(560,160,'A calendar wheel with four marked dates for four regions',f'<rect width="560" height="160" fill="#fffaf0"/>'+g(150,80,1,'<circle r="62" fill="#fff8e7"/><circle r="40" fill="#e3eaf3"/>'+''.join(f'<circle cx="{51*__import__("math").cos(a)}" cy="{51*__import__("math").sin(a)}" r="8" fill="{c}"/>' for a,c in [(-1.6,'#c0392b'),(-0.2,'#e0a800'),(1.6,'#2a5aa8'),(2.6,'#2a9d6f')]))+''.join(lab(400,30+k*28,t) for k,t in enumerate(['Caitra Pūrṇimā: north','Vaiśākha Daśamī: Telugu','Mārgaśīrṣa Śu. 13: Karnataka','Mārgaḻi new moon: Tamil']))),['<b>No single date in the epic.</b> Vālmīki tells of Hanumān’s birth but gives no calendar date for it. Later Purāṇas, almanacs and regional traditions each settled on their own, so Hanumān has several “birthdays”.','<b>Karnataka.</b> Kannada country keeps the <b>Hanumad vrata</b> on the thirteenth of the bright fortnight of Mārgaśīrṣa, in November or December, with a vow, a fast and a sacred thread. Some families keep Caitra Pūrṇimā too.','<b>Elsewhere.</b> Most of the north keeps Caitra Pūrṇimā, a week after '+L('/festivals/rama-navami/','Rāma Navamī')+'; Telugu devotees keep a 41-day dīkṣā ending on Vaiśākha Daśamī; Tamil Nadu and Kerala the new moon of Mārgaḻi when the Mūla star prevails; Odisha the solar new year, Pāṇa Saṅkrānti.','<b>One devotion.</b> Whatever the day, the worship is the same: the Cālīsā or the Sundara Kāṇḍa read, sindūra and oil on the image, garlands, and food for everyone.'],[('z','Which one should I keep?'),('b','Your family’s, Zappy. In Karnataka, that’s usually the Hanumad vrata in Mārgaśīrṣa.')],'Many dates, <b>one devotion</b>.'),
 story('birth','AÑJANĀ’S SON','The birth of Hanumān',strip('Three panels: an apsaras cursed to become a vānara; Añjanā praying on a hill; the wind god bringing her a child',[panel([(person('#7a3fa0'),1),(sage('#ff8c1a'),.9)],'#e9e3f5',150),panel([(mountain('#8a9a8a',False),.8),(person('#c98a3a'),.8)],'#fff3cf',150),panel([('<path d="M-40 -60 q30 -20 60 0 q-30 20 -60 0" fill="#cfe0f0"/>',1),(baby(),1)],'#dfe9f6',150)],['the curse','Añjanā’s prayer','the wind’s gift']),'Vālmīki, Kiṣkindhā Kāṇḍa 66, where Jāmbavān reminds Hanumān who he is, and later retellings.',['<b>Puñjikasthalā</b>, an apsaras of heaven, was cursed to be born on earth as a vānara; she became <b>Añjanā</b>, wife of the vānara chief <b>Kesarī</b>.','Añjanā longed for a son and prayed, by many tellings to Śiva, for years.','One day, as she stood on a mountain top in human form, the wind god <b>Vāyu</b> embraced her unseen and promised her a son as strong as himself, swift and wise.','In one well-loved telling, a kite snatched a portion of the divine pāyasa from Daśaratha’s sacrifice and dropped it, and Vāyu carried it to Añjanā’s hands: so Hanumān was born of the same gift as Rāma.','She gave birth in a cave on the mountain, and was freed of her curse. The child was <b>Āñjaneya</b> (Añjanā’s son), <b>Māruti</b> and <b>Pavanaputra</b> (the wind’s son).'],[('z','So he has two fathers?'),('b','Kesarī raised him, Vāyu gave him his power, Zappy. Many tellings also call him a portion of Śiva.')],'The <b>wind’s son</b>.'),
 story('sun','THE LEAP AT THE SUN','How Hanumān got his name',strip('Three panels: the hungry baby seeing the red rising sun; leaping into the sky; Indra striking him with the thunderbolt',[panel([(baby(),1),(sun(18),1)],'#fde9c8',150),panel([(H(),.8),(sun(18),1)],'#dfe9f6',150),panel([(god('#e0a800'),.9),(vajra(),.9),(H(),.6)],'#e9e3f5',150)],['a red fruit?','the leap','the thunderbolt']),'Vālmīki, Kiṣkindhā Kāṇḍa 66; the Purāṇas add the boons.',['As a baby, hungry, Hanumān saw the rising sun and took it for a ripe red fruit.','He leapt into the sky after it, flying higher and higher, toward the sun.','<b>Indra</b>, alarmed, hurled his thunderbolt (<i>vajra</i>). It struck the child on the jaw (<i>hanu</i>) and he fell to the mountain: hence <b>Hanumān</b>, “the one with the (marked) jaw”.','Furious, Vāyu withdrew into a cave with his son, and all breath stopped in the world. The gods hurried to make peace.','Brahmā revived the child, and every god gave him a boon: no weapon could kill him, he could change his size at will, he would live long and be wise. A sage’s curse made him forget his powers until someone reminded him, which Jāmbavān does before the leap to Laṅkā.'],[('z','He forgot his own powers?'),('b','Until he needed them, Zappy. Then one friend reminded him, and he crossed the ocean. A lesson for all of us.')],'Strength <b>remembered when needed</b>.'),
 verse('v-manojavam','Manojavaṃ','The verse of refuge in Rāma’s messenger',['manojavaṃ mārutatulyavegaṃ','jitendriyaṃ buddhimatāṃ variṣṭham','vātātmajaṃ vānarayūthamukhyaṃ','śrīrāmadūtaṃ śaraṇaṃ prapadye'],svg(200,150,'Hanumān flying with folded hands',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(100,110,1.1,H(),rot=-15)+'<path d="M20 120 q40 -10 60 -40" stroke="#cfe0f0" stroke-width="6" fill="none"/>'),'Swift as the mind, fast as the wind, master of the senses, foremost among the wise, son of the wind, chief of the vānara bands, messenger of Śrī Rāma: in him I take refuge.',[('mano-javam','swift as the mind'),('māruta-tulya-vegam','fast as the wind'),('jita-indriyam','master of the senses'),('buddhimatāṃ variṣṭham','best of the wise'),('vānara-yūtha-mukhyam','leader of the vānara bands'),('śaraṇaṃ prapadye','I take refuge')],'<b>Strength and wisdom together.</b> This is the verse most Karnataka children learn first for Hanumān. It praises not only his speed and strength but his self-mastery and intelligence: in Vālmīki, Rāma is struck by how well Hanumān speaks at their first meeting.',k='Swift as the mind, <b>master of himself</b>.',note='Text as on our '+L('/hanuman/slokas/','Hanumān ślokas')+' page.'),
 story('lanka','THE LEAP TO LAṄKĀ','Sundara Kāṇḍa in five',strip('Three panels: Hanumān leaping over the ocean; finding Sītā under a tree in the aśoka grove and giving the ring; Laṅkā burning from his tail',[panel([(H(),.8),(ocean(),1)],'#dfe9f6',None),panel([(SITA(),.9),(tree(),.6),(ring(),1)],'#e3f5e9',150),panel([(palace(),.6),(flames(),.9)],'#2a2a3a',150)],['across the sea','Rāma’s ring','Laṅkā burns']),'Vālmīki’s Sundara Kāṇḍa, the “beautiful book”, Hanumān’s own.',['The search party reached the southern sea. No one could jump a hundred yojanas. <b>Jāmbavān</b> reminded Hanumān of his birth and powers; Hanumān grew to the size of a mountain and leapt from Mahendra hill.','Across the ocean he overcame the serpent-mother Surasā by shrinking, the shadow-catching demoness Siṃhikā by force, and landed in <b>Laṅkā</b> at dusk.','He searched the city by night and found <b>Sītā</b> in the aśoka grove, guarded by rākṣasīs, refusing Rāvaṇa. He showed her <b>Rāma’s ring</b>; she gave him her hair-jewel to take back.','He wrecked the grove, let himself be captured, and spoke to Rāvaṇa’s face. When they set his tail on fire, he leapt from roof to roof and set Laṅkā ablaze.','He flew back with the news: “<b>dṛṣṭā sītā</b>”, Sītā has been seen. Reading the Sundara Kāṇḍa is the commonest way to keep Hanumān Jayantī.'],[('z','Why is it called the beautiful book?'),('b','Many reasons are given, Zappy. The simplest: it’s the book where hope comes back.')],'“<b>Sītā has been seen.</b>”'),
 story('sanjivani','THE MOUNTAIN OF HERBS','Saving Lakṣmaṇa',strip('Three panels: Lakṣmaṇa lying wounded with Rāma grieving; Hanumān lifting a whole mountain; the herbs reviving Lakṣmaṇa',[panel([(god('#e0a800'),.8,),(RAMA(),.9)],'#fde4e4',150),panel([(H(),.8),(herbhill(),.7)],'#dfe9f6',150),panel([(god('#e0a800'),.9),(RAMA(),.9),(H(),.7)],'#fff3cf',150)],['Lakṣmaṇa falls','the whole mountain','dawn and life']),'Yuddha Kāṇḍa; the details vary between the Vālmīki text and later retellings.',['In the war, <b>Lakṣmaṇa</b> fell, struck by a terrible weapon, and lay as if dead. Rāma wept beside him.','The physician <b>Suṣeṇa</b> said only the herbs of a Himālayan mountain, the life-giving <b>Sañjīvanī</b> among them, could save him, and they had to arrive before dawn.','Hanumān flew north. At the mountain the herbs hid from him; not knowing which was which, he lifted the whole peak and flew back with it.','The herbs were applied and Lakṣmaṇa rose, and the army rejoiced. In many tellings the mountain was then carried back.','That is why Hanumān is so often shown flying with a mountain in his palm, and why he is the god of healing and protection in Karnataka’s village shrines.'],[('z','He didn’t know which herb?'),('b','So he brought them all, Zappy. When love is in a hurry, it doesn’t stop to sort.')],'When in doubt, <b>bring the mountain</b>.'),
 verse('v-buddhi','Buddhir balaṃ','What remembering Hanumān gives',['buddhir balaṃ yaśo dhairyaṃ','nirbhayatvam arogatā','ajāḍyaṃ vākpaṭutvaṃ ca','hanūmat smaraṇād bhavet'],svg(200,150,'Eight small icons around Hanumān: a book, a mace, a star, a mountain, a shield, a leaf, a sun, a speech bubble',f'<rect width="200" height="150" fill="#e3eaf3"/>'+g(100,135,1.1,H())+''.join(g(100+70*__import__("math").cos(a),70+50*__import__("math").sin(a),.5,lamp()) for a in [-2.6,-2.0,-1.4,-0.8,-0.2])),'Intelligence, strength, fame, courage, fearlessness, health, alertness and eloquence come from remembering Hanumān.',[('buddhiḥ','intelligence'),('balam','strength'),('dhairyam','courage'),('nirbhayatvam','fearlessness'),('arogatā','health'),('vāk-paṭutvam','skill in speech')],'<b>A list for students.</b> This verse is a favourite before exams in Karnataka homes: it asks Hanumān for the things a young person needs, and notice that intelligence comes first and strength second. <i>Ajāḍyam</i>, freedom from dullness, is a fine thing to ask for.',k='Brains first, <b>then brawn</b>.',note='Text as on our '+L('/hanuman/slokas/','Hanumān ślokas')+' page.'),
 reading('vrata','THE HANUMAD VRATA','Karnataka’s Hanumān day',svg(560,160,'A devotee tying a red thread with thirteen knots before Hanumān, with a plate of offerings',f'<rect width="560" height="160" fill="#e3eaf3"/>'+'<rect y="130" width="560" height="30" fill="#c9d6e6"/>'+g(170,130,1.2,H())+g(300,135,1.1,namaste('#c0392b'))+'<path d="M340 90 h120" stroke="#c0392b" stroke-width="3"/>'+''.join(f'<circle cx="{344+k*9}" cy="90" r="3" fill="#c0392b"/>' for k in range(13))+g(450,135,1.2,plate())),['<b>The day.</b> Mārgaśīrṣa Śukla Trayodaśī, in the cold season. Devotees fast, bathe early, and worship Hanumān at home or in the village Āñjaneya temple.','<b>The thread.</b> The vrata centres on a sacred red thread with <b>thirteen knots</b>, one for the thirteenth tithi, worshipped and then tied on the wrist, to be kept for a year by many.','<b>The worship.</b> The image is anointed with oil and sindūra, decked with betel leaves (<i>vīḷyada ele</i>) and tulasī, and offered vaḍe, pongal, laḍḍu and fruit. The Cālīsā, the Sundara Kāṇḍa or the Hanumān ślokas are recited.','<b>The next day.</b> Mārgaśīrṣa Pūrṇimā follows: Datta Jayantī. Many temples hold a car festival or a procession on the vrata day itself.'],[('z','Why oil and sindūra on Hanumān?'),('b','A beloved story says he saw Sītā wear sindūra for Rāma’s long life and covered himself in it, Zappy. If a little helps Rāma, a lot must help more.')],'A <b>thread of thirteen knots</b>.'),
 reading('anjanadri','AÑJANĀDRI AND THE HANUMĀN-MĀLĀ','Lakhs on one hill near Hampi',svg(560,170,'A rocky hill with white steps winding to a temple at the top and crowds in saffron climbing',f'<rect width="560" height="170" fill="#fde9c8"/>'+'<path d="M120 170 q60 -150 160 -150 q100 0 160 150z" fill="#b8a080"/>'+'<path d="M200 170 q30 -40 60 -60 q20 -20 20 -60" fill="none" stroke="#fff" stroke-width="5" stroke-dasharray="6 4"/>'+g(280,26,.5,palace())+''.join(g(x,y,.5,person('#ff8c1a')) for x,y in [(210,160),(232,140),(255,115),(268,90),(275,68)])+'<path d="M0 160 q80 -6 120 10" stroke="#5a8ab8" stroke-width="8" fill="none"/>'),['<b>The hill.</b> Añjanādri, in Gaṅgāvati taluk of Koppaḷa district across the Tuṅgabhadrā from Hampi, is revered in local tradition as Hanumān’s birthplace, in the Kiṣkindhā country of the Rāmāyaṇa. About 575 steps climb to the small white temple on top.','<b>The mālā.</b> Devotees wear a <b>Hanumān-mālā</b> for 11, 21 or 41 days, keeping a simple, disciplined life, then climb the hill around the Hanumad vrata to remove it: the <b>Hanumamālā visarjane</b>. The practice is recent, a few decades old, and now draws lakhs; the district arranges routes and the hill is lit at night.','<b>Other claims.</b> Añjanēri near Nāsik, a hill at Tirumala, Āñjan Dhām in Jharkhand and others also claim his birth. These are devotional traditions; none can be proved, and each is dear to its devotees.','<b>Around.</b> Pampā Sarovara, Ṛṣyamūka and the Hampi temples are all close; see our '+L('/hanuman/stories/kishkindha/','Kiṣkindhā story')+'.'],[('z','Which birthplace is right?'),('b','Each has its tradition, Zappy. A god can be born in many hearts.')],'A hill <b>turned saffron</b>.'),
 verse('v-chalisa','Hanumān Cālīsā, caupāī 1','Victory to Hanumān, ocean of wisdom',['jaya hanumāna jñāna guna sāgara','jaya kapīsa tihuṃ loka ujāgara'],svg(200,150,'Hanumān with the three worlds glowing behind him',f'<rect width="200" height="150" fill="#e3eaf3"/>'+''.join(f'<circle cx="100" cy="70" r="{r}" fill="none" stroke="#e0a800" stroke-width="2"/>' for r in (30,45,60))+g(100,140,1.1,H())),'Victory to Hanumān, ocean of wisdom and virtue; victory to the lord of the vānaras, who lights up the three worlds.',[('jaya','victory'),('jñāna','wisdom'),('guna','good qualities'),('sāgara','ocean'),('kapīsa','lord of the monkeys'),('tihuṃ loka ujāgara','illuminating the three worlds')],'<b>The forty verses.</b> Tulasīdās’s Hanumān Cālīsā, in Avadhī, is the most recited prayer in India. On Hanumān Jayantī it is sung in every temple, often 11 or 108 times. Our full Cālīsā pages go verse by verse.',k='<b>Ocean of wisdom</b>, lord of all three worlds.',note='Text as on our '+L('/hanuman/chalisa/','Hanumān Cālīsā')+' page (Avadhī in IAST).'),
 cards('south','HANUMĀN ACROSS THE SOUTH','Vaḍe garlands, butter and giant images',fig_row('A garland of vaḍas, a pot of butter, betel leaves and a giant image',[(vadamala(),1),(pot('#fff8e7'),1.3),(leaf('#3a8a3a'),1.6),(H(),1.1)],['vaḍe-mālā','veṇṇe','vīḷyada ele','giant Hanumān'],gy=150),[('🍩','Vaḍe-mālā','Garlands of hundreds or thousands of vaḍes: famous at Namakkal in Tamil Nadu, where the eighteen-foot Āñjaneya receives lakhs on Hanumat Jayantī, and common in Karnataka temples too.'),('🧈','Butter','Images are covered in butter (<i>veṇṇe kāppu</i>), which does not melt, devotees say, while Hanumān is pleased.'),('🌿','Betel leaves','Garlands of betel leaves: one story says Sītā, having no flowers in the aśoka grove, blessed him with a betel-leaf garland.'),('🗿','Giants','Huge Hanumān images draw pilgrims: Śucīndram in Tamil Nadu, Bengaluru’s Ragigudda and Mahālakṣmī Layout, and the countless hill-top Āñjaneyas of Karnataka.')],[('z','Thousands of vaḍes!'),('b','And every one goes back to the devotees as prasāda, Zappy. Hanumān shares.')],'Strength <b>shared as food</b>.'),
 reading('meaning','WHAT HANUMĀN MEANS','Strength in service',svg(560,150,'Hanumān kneeling before Rāma and Sītā with folded hands',f'<rect width="560" height="150" fill="#e3eaf3"/>'+'<rect y="125" width="560" height="25" fill="#c9d6e6"/>'+g(300,130,1.2,RAMA())+g(360,130,1.1,SITA())+g(200,132,1,namaste('#c0582a'))),['<b>The servant.</b> Hanumān has every power and uses none for himself. Asked who he is, the tradition has him answer: as a body, I am your servant; as a soul, I am your part; in truth, I am you. Devotion, strength and wisdom in one person. (A well-known verse attributed to Hanumān; textual source uncertain.)','<b>Humility.</b> He forgets his own powers until reminded, and always credits Rāma. Many teachers read this as the secret of his strength. (Interpretation.)','<b>The guardian.</b> At the boundary of the village, Āñjaneya protects; that is why his shrines are so many and so old in Karnataka.','<b>The speaker.</b> Vālmīki has Rāma praise Hanumān’s grammar and diction at their first meeting: the strongest of the vānaras was also the most articulate.'],[('z','If I could do one thing for Hanumān Jayantī?'),('b','Read one canto of the Sundara Kāṇḍa, Zappy, and do one hard job for someone else without telling anyone.')],'All strength, <b>no ego</b>.'),
 end(i,['<b>Dates.</b> Karnataka: Mārgaśīrṣa Śu. 13 (Hanumad vrata); north: Caitra Pūrṇimā.','<b>Birth.</b> Añjanā and Kesarī; the wind god Vāyu; the leap at the sun.','<b>Deeds.</b> The leap to Laṅkā, Sītā found; the mountain of herbs.','<b>Verses.</b> Manojavaṃ; buddhir balaṃ; the Cālīsā.','<b>Karnataka.</b> Thirteen-knot thread; Añjanādri and the Hanumān-mālā.'],'Previous: '+L('/festivals/vaikuntha-ekadashi/','Vaikuṇṭha Ekādaśī')+'. More: our '+L('/hanuman/stories/','Hanumān stories')+'.','Hanumān Jayantī: Rāma’s messenger'),
 sources([('Texts:','Vālmīki Rāmāyaṇa, Kiṣkindhā Kāṇḍa 66 (birth, leap at the sun, Jāmbavān), Sundara and Yuddha Kāṇḍas; Brahmāṇḍa and Varāha Purāṇas for the boons (via Wikipedia); Eknāth’s Bhāvārtha Rāmāyaṇa for the kite and pāyasa telling. Verses from our Hanumān ślokas and Cālīsā pages.'),('Dates and customs:','Wikipedia, “Hanuman Jayanti” (regional dates, birthplace claims, customs); Karnataka practice and Añjanādri from regional sources summarised in our earlier guide.')],'regional dates (traditions differ); the thirteen-knot thread (tradition); the sindūra and betel-leaf stories (popular); birthplace claims (devotional, unprovable); the “dāsoham” verse attributed to Hanumān (source uncertain); Hanumān-mālā history and numbers (as reported).','Interpretations are marked as such.')]
build(i,'HANUMAD VRATA · THE WIND’S SON · AÑJANĀDRI',COV,'The leap across the sea','Why Hanumān has <b>several birthdays</b>, his <b>birth</b> and the leap at the sun, his great <b>deeds</b>, three <b>verses</b>, and Karnataka’s <b>Hanumad vrata</b> and Añjanādri.','Hanumān Jayantī explained: the regional dates and Karnataka’s Hanumad vrata, Añjanā and Vāyu, the leap at the sun, the leap to Laṅkā and the mountain of herbs, the Manojavaṃ and Buddhir balaṃ verses, the Hanumān Cālīsā, Añjanādri and the Hanumān-mālā near Hampi.',pp)
print('hj ok',len(pp)+2)
